 const allowed=l=>l&&Array.isArray(l.roles)&&l.roles.length===2&&l.roles.every(r=>Object.hasOwn(point,r.pointId)&&typeof r.name==="string"&&r.name.trim()&&typeof r.chartId==="string")&&Object.hasOwn(aspect,l.aspectId)&&Array.isArray(l.evidenceIds)&&l.evidenceIds.length===1&&l.evidenceIds[0]==="contact:"+l.contactId;
 const chapterLabels={"communication":"گفت‌وگو","emotional-security":"امنیت عاطفی","attraction-intimacy":"کشش و صمیمیت","boundaries-commitment":"مرز و تعهد","friction-repair":"اصطکاک و ترمیم"};
